create table public.profiles (id uuid primary key references auth.users(id) on delete cascade, email text not null, created_at timestamptz not null default now());
create table public.meal_prices (id uuid primary key default gen_random_uuid(), user_id uuid not null references auth.users(id) on delete cascade, breakfast_price numeric(10,2) not null check(breakfast_price>=0), lunch_price numeric(10,2) not null check(lunch_price>=0), dinner_price numeric(10,2) not null check(dinner_price>=0), full_day_price numeric(10,2) not null check(full_day_price>=0), effective_from date not null default current_date, created_at timestamptz not null default now());
create table public.tally_groups (id uuid primary key default gen_random_uuid(), user_id uuid not null references auth.users(id) on delete cascade, amount numeric(10,2) not null check(amount>=0), meal_count integer not null check(meal_count=3), status text not null default 'active' check(status in ('active','reopened')), created_at timestamptz not null default now());
create table public.meals (id uuid primary key default gen_random_uuid(), user_id uuid not null references auth.users(id) on delete cascade, meal_date date not null, meal_type text not null check(meal_type in ('breakfast','lunch','dinner')), price_snapshot numeric(10,2) not null check(price_snapshot>=0), status text not null default 'untallied' check(status in ('untallied','tallied')), tally_group_id uuid references public.tally_groups(id), created_at timestamptz not null default now(), updated_at timestamptz not null default now(), unique(user_id,meal_date,meal_type));
create table public.payments (id uuid primary key default gen_random_uuid(), user_id uuid not null references auth.users(id) on delete cascade, amount numeric(10,2) not null check(amount>0), payment_date date not null, note text, created_at timestamptz not null default now());
create table public.monthly_closures (id uuid primary key default gen_random_uuid(), user_id uuid not null references auth.users(id) on delete cascade, year integer not null, month integer not null check(month between 1 and 12), closed_at timestamptz, status text not null default 'open' check(status in ('open','closed')), unique(user_id,year,month));
create index meals_user_date_idx on public.meals(user_id,meal_date); create index payments_user_date_idx on public.payments(user_id,payment_date);
alter table public.profiles enable row level security; alter table public.meal_prices enable row level security; alter table public.meals enable row level security; alter table public.tally_groups enable row level security; alter table public.payments enable row level security; alter table public.monthly_closures enable row level security;
create policy "own profiles" on public.profiles for all using(auth.uid()=id) with check(auth.uid()=id); create policy "own prices" on public.meal_prices for all using(auth.uid()=user_id) with check(auth.uid()=user_id); create policy "own meals" on public.meals for all using(auth.uid()=user_id) with check(auth.uid()=user_id); create policy "own groups" on public.tally_groups for all using(auth.uid()=user_id) with check(auth.uid()=user_id); create policy "own payments" on public.payments for all using(auth.uid()=user_id) with check(auth.uid()=user_id); create policy "own closures" on public.monthly_closures for all using(auth.uid()=user_id) with check(auth.uid()=user_id);
create or replace function public.reopen_tally(group_id uuid) returns void language plpgsql security invoker as $$ begin update public.meals set tally_group_id=null,status='untallied',updated_at=now() where tally_group_id=group_id and user_id=auth.uid(); update public.tally_groups set status='reopened' where id=group_id and user_id=auth.uid(); end; $$;
create or replace function public.create_profile() returns trigger language plpgsql security definer set search_path=public as $$ begin insert into public.profiles(id,email) values(new.id,new.email); insert into public.meal_prices(user_id,breakfast_price,lunch_price,dinner_price,full_day_price) values(new.id,50,100,50,200); return new; end; $$; create trigger on_auth_user_created after insert on auth.users for each row execute procedure public.create_profile();
